#!/bin/bash
# ============================================================
# DESPLIEGUE: logo de Daniela en la web drgsoul.com
#  1. Instala favicon (logo iridiscente) en 512/192 + apple-touch
#  2. Actualiza <title> y etiquetas de ícono en index.html
#  3. Inserta el logo en la barra de navegación junto a "DRG Soul"
#  Con respaldo previo y verificación. Si algo no calza, NO rompe:
#  reporta las líneas reales para ajustar.
# ============================================================
set -u
WEB=/root/drgsoul-web
cd "$WEB" || { echo "ERROR: no existe $WEB"; exit 1; }
[ -f index.html ] || { echo "ERROR: no hay index.html en $WEB"; exit 1; }

FECHA=$(date +%Y%m%d-%H%M%S)
cp index.html "index.html.bak-$FECHA"
echo "Respaldo: index.html.bak-$FECHA"

echo "Escribiendo íconos..."
base64 -d > favicon-512.png << 'B64A'

B64A
base64 -d > favicon-192.png << 'B64B'

B64B
base64 -d > apple-touch-icon.png << 'B64C'

B64C
cp favicon-512.png logo-drg.png
echo "Íconos escritos: favicon-512.png, favicon-192.png, apple-touch-icon.png, logo-drg.png"

echo "Parcheando index.html..."
python3 << 'PYEOF'
import re, sys

html = open("index.html", encoding="utf-8").read()
cambios = []
avisos = []

# ---------- 1. Título de la pestaña ----------
nuevo_titulo = "DRG Soul · Daniela Rodríguez — Psicóloga humanista"
if re.search(r"<title>.*?</title>", html, re.S):
    html = re.sub(r"<title>.*?</title>", f"<title>{nuevo_titulo}</title>", html, count=1, flags=re.S)
    cambios.append("título actualizado")
else:
    html = html.replace("<head>", f"<head>\n<title>{nuevo_titulo}</title>", 1)
    cambios.append("título insertado")

# ---------- 2. Favicon: quitar los actuales y poner el logo ----------
quitados = len(re.findall(r'<link[^>]+rel="(?:shortcut )?icon"[^>]*>', html))
html = re.sub(r'\s*<link[^>]+rel="(?:shortcut )?icon"[^>]*>', "", html)
html = re.sub(r'\s*<link[^>]+rel="apple-touch-icon"[^>]*>', "", html)
iconos = ('<link rel="icon" type="image/png" sizes="512x512" href="/favicon-512.png">\n'
          '<link rel="icon" type="image/png" sizes="192x192" href="/favicon-192.png">\n'
          '<link rel="apple-touch-icon" href="/apple-touch-icon.png">')
html = re.sub(r"(</title>)", r"\1\n" + iconos, html, count=1)
cambios.append(f"favicon reemplazado (quitados {quitados} anteriores)")

# ---------- 3. Logo en la barra de navegación ----------
# Busca el elemento de marca. Intenta variantes conocidas.
patrones_brand = [
    r'(<div class="brand">)(\s*DRG)',
    r'(<a class="brand"[^>]*>)(\s*DRG)',
    r'(class="brand"[^>]*>)(\s*DRG)',
]
puesto = False
for p in patrones_brand:
    if re.search(p, html):
        html = re.sub(p, r'\1<img src="/logo-drg.png" alt="DRG" class="brand-logo">\2', html, count=1)
        puesto = True
        cambios.append("logo insertado en la marca del nav")
        break
if not puesto:
    avisos.append("NO encontré el elemento de marca del nav. Líneas candidatas:")
    for i, l in enumerate(html.split("\n"), 1):
        if "brand" in l.lower() or ("DRG" in l and "Soul" in l):
            avisos.append(f"  línea {i}: {l.strip()[:120]}")

# CSS del logo (solo si se insertó)
if puesto and ".brand-logo" not in html:
    css = (".brand{display:flex;align-items:center;gap:10px}"
           ".brand-logo{height:34px;width:auto;display:block}")
    html = html.replace("</style>", css + "\n</style>", 1)
    cambios.append("CSS del logo añadido")

open("index.html", "w", encoding="utf-8").write(html)
print("CAMBIOS:", "; ".join(cambios))
for a in avisos:
    print("AVISO:", a)
sys.exit(0)
PYEOF

# ---------- Verificación ----------
echo
echo "Verificando..."
grep -c "favicon-512" index.html && echo "  favicon OK" || echo "  FALTA favicon"
grep -c "brand-logo" index.html >/dev/null && echo "  logo en nav OK" || echo "  logo en nav: revisar aviso de arriba"
grep -o "<title>[^<]*</title>" index.html

# ¿Hay más páginas html que también necesiten el favicon?
OTRAS=$(ls *.html 2>/dev/null | grep -v index.html || true)
[ -n "$OTRAS" ] && echo "OJO, hay otras páginas (avísale a Claude): $OTRAS"

systemctl restart drgsoul-web.service 2>/dev/null && echo "Servicio reiniciado"
sleep 2
CODE=$(curl -s -o /dev/null -w "%{http_code}" http://localhost:8080/)
echo "Respuesta del sitio: HTTP $CODE"
ICO=$(curl -s -o /dev/null -w "%{http_code}" http://localhost:8080/favicon-512.png)
echo "Favicon servido: HTTP $ICO"
echo
echo "LISTO. Abre https://drgsoul.com y fuerza recarga (Ctrl+Shift+R)."
echo "El favicon puede tardar en refrescar por caché del navegador."
